package com.xdownload.mobile;
import android.app.*;import android.content.*;import android.net.*;import android.os.*;import android.provider.OpenableColumns;import android.widget.*;import java.io.*;import java.net.*;import java.security.*;import java.util.*;import java.util.concurrent.*;
/** Explicit single-file sharing on the current trusted Wi-Fi network. No directory listing. */
public final class LanShareActivity extends SecureActivity{
 final ExecutorService io=Executors.newSingleThreadExecutor();volatile ServerSocket server;volatile Socket client;volatile boolean closed=false,cancelled=false;TextView status;Button choose;volatile String link="";
 @Override public void onCreate(Bundle b){super.onCreate(b);LinearLayout l=new LinearLayout(this);l.setOrientation(1);l.setPadding(24,24,24,24);status=new TextView(this);status.setText("Share one file or a ZIP of up to 20 selected files with a browser on the same trusted Wi-Fi. Local HTTP is not encrypted; do not use on public Wi-Fi. Link expires after 3 minutes or one successful GET. Keep this screen open.");l.addView(status);choose=new Button(this);choose.setText("Choose files to share");choose.setOnClickListener(v->startActivityForResult(new Intent(Intent.ACTION_OPEN_DOCUMENT).addCategory(Intent.CATEGORY_OPENABLE).setType("*/*").putExtra(Intent.EXTRA_ALLOW_MULTIPLE,true),80));l.addView(choose);Button copy=new Button(this);copy.setText("Copy temporary link");copy.setOnClickListener(v->{if(!link.isEmpty())((android.content.ClipboardManager)getSystemService(CLIPBOARD_SERVICE)).setPrimaryClip(ClipData.newPlainText("Local share",link));});l.addView(copy);Button stop=new Button(this);stop.setText("Stop sharing");stop.setOnClickListener(v->{stop();status.setText("Stopping…");});l.addView(stop);setContentView(l);}
 @Override protected void onActivityResult(int r,int result,Intent data){super.onActivityResult(r,result,data);if(r!=80||result!=RESULT_OK||data==null)return;LinkedHashSet<Uri> files=new LinkedHashSet<>();if(data.getData()!=null)files.add(data.getData());ClipData clip=data.getClipData();if(clip!=null){if(clip.getItemCount()>20){status.setText("Select at most 20 files");return;}for(int i=0;i<clip.getItemCount();i++)if(clip.getItemAt(i).getUri()!=null)files.add(clip.getItemAt(i).getUri());}if(files.isEmpty()||files.size()>20)return;cancelled=false;choose.setEnabled(false);status.setText("Preparing Wi-Fi share…");io.execute(()->{File zip=null;try{if(files.size()==1)serve(files.iterator().next(),null);else{zip=pack(files);if(!cancelled&&!closed)serve(null,zip);}}catch(Exception ex){report("Share failed: "+ex.getMessage(),true);}finally{if(zip!=null)zip.delete();}});}
 InetAddress wifiAddress()throws Exception{ConnectivityManager cm=getSystemService(ConnectivityManager.class);Network network=cm.getActiveNetwork();NetworkCapabilities caps=cm.getNetworkCapabilities(network);if(caps==null||!caps.hasTransport(NetworkCapabilities.TRANSPORT_WIFI))throw new IOException("Connect to trusted Wi-Fi first");LinkProperties props=cm.getLinkProperties(network);if(props!=null)for(LinkAddress address:props.getLinkAddresses()){InetAddress a=address.getAddress();if(a instanceof Inet4Address&&!a.isLoopbackAddress()&&a.isSiteLocalAddress())return a;}throw new IOException("No private Wi-Fi IPv4 address");}
 File pack(Collection<Uri> files)throws Exception{File zip=File.createTempFile("studio-out-",".zip",getCacheDir());boolean ok=false;long total=0;HashSet<String> used=new HashSet<>();try{try(java.util.zip.ZipOutputStream out=new java.util.zip.ZipOutputStream(new BufferedOutputStream(new FileOutputStream(zip)))){for(Uri u:files){String name=DownloadDestination.name(this,u,"file");out.putNextEntry(new java.util.zip.ZipEntry(FileTools.uniqueEntry(name,used)));try(InputStream in=getContentResolver().openInputStream(u)){if(in==null)throw new IOException("Cannot read file");byte[] buf=new byte[65536];int n;while((n=in.read(buf))!=-1){if(cancelled||closed||Thread.currentThread().isInterrupted())throw new IOException("Cancelled");total+=n;if(total>512L*1024*1024||getCacheDir().getUsableSpace()<16L*1024*1024)throw new IOException("ZIP/storage limit");out.write(buf,0,n);}}out.closeEntry();}}ok=true;return zip;}finally{if(!ok)zip.delete();}}
 void serve(Uri uri,File zip){ServerSocket local=null;try{String name=zip==null?"download":"XDownload-share.zip";long length=zip==null?-1:zip.length();if(zip==null)try(android.database.Cursor c=getContentResolver().query(uri,new String[]{OpenableColumns.DISPLAY_NAME,OpenableColumns.SIZE},null,null,null)){if(c!=null&&c.moveToFirst()){name=HttpEngine.safeName(c.getString(0));if(!c.isNull(1))length=c.getLong(1);}}if(length<0)throw new IOException("Provider must expose file size");InetAddress address=wifiAddress();byte[] key=new byte[24];new SecureRandom().nextBytes(key);String token=android.util.Base64.encodeToString(key,android.util.Base64.URL_SAFE|android.util.Base64.NO_WRAP|android.util.Base64.NO_PADDING);local=new ServerSocket(0,4,address);local.setSoTimeout(1000);server=local;if(closed||cancelled)throw new IOException("Closed");String url="http://"+address.getHostAddress()+":"+local.getLocalPort()+"/"+token;link=url;report("Open this temporary link on the receiving device:\n"+url+"\nKeep the screen open.",false);long deadline=SystemClock.elapsedRealtime()+180000L;boolean sent=false;while(!closed&&!local.isClosed()&&!sent&&SystemClock.elapsedRealtime()<deadline){try(Socket sock=local.accept()){client=sock;sock.setSoTimeout(5000);BufferedReader in=new BufferedReader(new InputStreamReader(sock.getInputStream(),java.nio.charset.StandardCharsets.US_ASCII));String request=boundedLine(in,4096);for(int i=0;i<40;i++){String line=boundedLine(in,4096);if(line==null||line.isEmpty())break;}OutputStream out=sock.getOutputStream();if(request==null||!request.equals("GET /"+token+" HTTP/1.1")&&!request.equals("GET /"+token+" HTTP/1.0")){out.write("HTTP/1.1 404 Not Found\r\nContent-Length: 0\r\nConnection: close\r\n\r\n".getBytes(java.nio.charset.StandardCharsets.US_ASCII));continue;}String safe=name.replaceAll("[^a-zA-Z0-9._ -]","_");String header="HTTP/1.1 200 OK\r\nContent-Type: application/octet-stream\r\nContent-Disposition: attachment; filename=\""+safe+"\"\r\nContent-Length: "+length+"\r\nCache-Control: no-store\r\nConnection: close\r\n\r\n";out.write(header.getBytes(java.nio.charset.StandardCharsets.US_ASCII));long done=0;try(InputStream file=zip==null?getContentResolver().openInputStream(uri):new FileInputStream(zip)){if(file==null)throw new IOException("Cannot open file");byte[] buf=new byte[65536];int n;while(!closed&&!local.isClosed()&&(n=file.read(buf))!=-1){if(done+n>length)throw new IOException("File changed");out.write(buf,0,n);done+=n;}}out.flush();sent=done==length;}catch(SocketTimeoutException ignored){}finally{client=null;}}report(sent?"Transfer completed":"Sharing stopped or expired",true);}catch(Exception ex){report("Share stopped: "+ex.getMessage(),true);}finally{if(local!=null)try{local.close();}catch(IOException ignored){}server=null;link="";}}
 static String boundedLine(BufferedReader in,int limit)throws IOException{StringBuilder b=new StringBuilder();for(int i=0;i<limit;i++){int x=in.read();if(x<0)return b.length()==0?null:b.toString();if(x=='\n')return b.toString();if(x!='\r')b.append((char)x);}throw new IOException("Request too long");}
 void report(String s,boolean enable){runOnUiThread(()->{if(!closed){status.setText(s);choose.setEnabled(enable);}});}
 void stop(){cancelled=true;link="";Socket c=client;if(c!=null)try{c.close();}catch(Exception ignored){}ServerSocket s=server;if(s!=null)try{s.close();}catch(Exception ignored){}}
 @Override protected void onStop(){stop();super.onStop();}@Override protected void onDestroy(){closed=true;stop();io.shutdownNow();super.onDestroy();}
}